131	    public static String normalizeAddress(String address) {
132	        if (address == null) {
133	            return null;
134	        }
135	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
136	        if (collapsed.isEmpty()) {
137	            return "";
138	        }
139	        String[] tokens = collapsed.split(" ");
140	        StringBuilder sb = new StringBuilder();
141	        for (int i = 0; i < tokens.length; i++) {
142	            if (i > 0) {
143	                sb.append(' ');
144	            }
145	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
146	        }
147	        return sb.toString();
