254	     * Return a single Luhn check digit (0-9) computed over the digits contained in
255	     * the owner's customer code, or {@code null} when the customer code is not set.
256	     * Non-digit characters in the code are ignored; the rightmost digit is doubled
257	     * first, following the standard Luhn algorithm.
258	     */
259	    public Integer getCheckDigit() {
260	        if (this.customerCode == null) {
261	            return null;
262	        }
263	        int sum = 0;
264	        boolean doubleDigit = true;
265	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
266	            char c = this.customerCode.charAt(i);
267	            if (c < '0' || c > '9') {
268	                continue;
269	            }
270	            int digit = c - '0';
271	            if (doubleDigit) {
272	                digit *= 2;
273	                if (digit > 9) {
274	                    digit -= 9;
275	                }
276	            }
277	            sum += digit;
278	            doubleDigit = !doubleDigit;
279	        }
280	        return (10 - (sum % 10)) % 10;
281	    }
