397	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
398	     * known range.
399	     */
400	    private String regionForPostcode() {
401	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
402	            return null;
403	        }
404	        int value = Integer.parseInt(this.postcode);
405	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
406	            int[] range = entry.getValue();
407	            if (value >= range[0] && value <= range[1]) {
408	                return entry.getKey();
409	            }
410	        }
411	        return null;
412	    }
