428	     * The telephone and email are already stored in their normalized (E.164 /
429	     * lower-cased) forms; a missing email or household id contributes an empty
430	     * segment. A create is rejected only when a new owner's whole identity key
431	     * equals an existing owner's.
432	     */
433	    public String getIdentityKey() {
434	        String telephonePart = this.telephone == null ? "" : this.telephone;
435	        String emailPart = (this.email == null) ? "" : this.email;
436	        String householdPart = (this.householdId == null) ? "" : this.householdId;
437	        return telephonePart + "|" + emailPart + "|" + householdPart;
438	    }
