46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /** Dedicated audit trail for owner-lifecycle side effects. */
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
114	        if (normalizedTelephone == null) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
118	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        owner.setTelephone(normalizedTelephone);
123	        if (!owner.isPostcodeValidForCity()) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        // The household id is deterministic: it is derived purely from the owner's
127	        // (last name, postcode), so every owner at the same last name and postcode resolves
128	        // to the same value. It is assigned up front, before any duplicate detection, so the
129	        // identity key and the household check below both key off it.
130	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        // Consolidated hard-duplicate detection: reject only when the new owner's WHOLE
133	        // identityKey (telephone|email|householdId) equals an existing owner's. With the
134	        // household id now computed up front, two members of one household still differ here
135	        // whenever their telephone or email differs, and so are both allowed.
136	        String identityKey = owner.getIdentityKey();
137	        if (this.clinicService.findAllOwners().stream()
138	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
139	            return new ResponseEntity<>(HttpStatus.CONFLICT);
140	        }
141	        // Household duplicate: because the household is keyed on (last name, postcode), any
142	        // existing owner sharing this computed household id is the same household. A second
143	        // such owner is rejected as a household duplicate (409) unless it explicitly declares
144	        // 'sharesHousehold', which now only bypasses this block (the link is no longer created
145	        // here — the id is computed).
146	        List<Owner> householdMembers = findHouseholdMembers(owner.getHouseholdId());
147	        if (!householdMembers.isEmpty() && !sharesHousehold) {
148	            return new ResponseEntity<>(HttpStatus.CONFLICT);
149	        }
150	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
151	            return new ResponseEntity<>(HttpStatus.CONFLICT);
152	        }
153	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
154	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
155	        }
156	        LocalDate effectiveDate =
157	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
158	        LocalDate registrationDate = toBusinessDay(effectiveDate);
159	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
160	        if (ownersRegisteredToday >= 100) {
161	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
162	        }
163	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
164	        HttpHeaders headers = new HttpHeaders();
165	        owner.setRegistrationDate(registrationDate);
166	        owner.setCustomerCode(customerCode(owner));
167	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
168	        owner.setBulkSignupWarning(bulkSignupWarning);
169	        // The household size (an input to the membership computation) keys off the computed
170	        // household id: this owner plus everyone already sharing it.
171	        owner.setHouseholdSize(householdMembers.size() + 1);
172	        // Soft-match ("possible duplicate"): a declared household member is not a suspected
173	        // duplicate, so only a non-declared create is scored. In practice a non-declared owner
174	        // sharing an existing owner's last name and postcode is already rejected above as a
175	        // household duplicate, so this now only ever confirms the owner is not a duplicate.
176	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
177	        owner.setPossibleDuplicate(possibleDuplicate != null);
178	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
179	        this.clinicService.saveOwner(owner);
180	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
181	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
182	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
183	        headers.setLocation(UriComponentsBuilder.newInstance()
184	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
185	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
186	    }
