188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
191	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
192	        if (currentOwner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
196	        if (normalizedTelephone == null) {
197	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
198	        }
199	        currentOwner.setAddress(ownerFieldsDto.getAddress());
200	        currentOwner.setCity(ownerFieldsDto.getCity());
201	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
202	        currentOwner.setLastName(ownerFieldsDto.getLastName());
203	        currentOwner.setTelephone(normalizedTelephone);
204	        currentOwner.setEmail(ownerFieldsDto.getEmail());
205	        this.clinicService.saveOwner(currentOwner);
206	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Transactional
211	    @Override
212	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
213	        Owner owner = this.clinicService.findOwnerById(ownerId);
214	        if (owner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        this.clinicService.deleteOwner(owner);
218	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner == null) {
226	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	        }
228	        HttpHeaders headers = new HttpHeaders();
229	        Pet pet = petMapper.toPet(petFieldsDto);
230	        owner.setId(ownerId);
231	        pet.setOwner(owner);
232	        pet.getType().setName(null);
233	        this.clinicService.savePet(pet);
234	        PetDto petDto = petMapper.toPetDto(pet);
235	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
236	            .buildAndExpand(pet.getId()).toUri());
237	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
238	    }
