240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
243	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
244	        if (currentOwner != null) {
245	            Pet currentPet = this.clinicService.findPetById(petId);
246	            if (currentPet != null) {
247	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
248	                currentPet.setName(petFieldsDto.getName());
249	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
250	                this.clinicService.savePet(currentPet);
251	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
252	            }
253	        }
254	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
260	        HttpHeaders headers = new HttpHeaders();
261	        Visit visit = visitMapper.toVisit(visitFieldsDto);
262	        Pet pet = new Pet();
263	        pet.setId(petId);
264	        visit.setPet(pet);
265	        this.clinicService.saveVisit(visit);
266	        VisitDto visitDto = visitMapper.toVisitDto(visit);
267	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
268	            .buildAndExpand(visit.getId()).toUri());
269	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
270	    }
271	
272	
273	    /**
274	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
275	     * stripped. When a leading {@code '+'} and country code are present they are kept;
276	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
277	     * is dropped from the national digits. The result must be a {@code '+'} followed
278	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
279	     * is returned to signal a bad request.
280	     */
281	    /**
282	     * Build the customer code for a newly created owner, formatted
283	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the region derived from the
284	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
285	     * derivation the locality uses), and {@code HASH8} is the first eight upper-case
286	     * hex characters of the SHA-256 of the owner's normalized telephone concatenated
287	     * with its last name. This identity carries no sequence number.
288	     */
289	    private String customerCode(Owner owner) {
290	        String region = owner.getLocality();
291	        String hash8 = customerCodeHash(owner.getTelephone(), owner.getLastName());
292	        return region + "-" + hash8;
293	    }
294	
295	    /**
296	     * Compute the {@code HASH8} portion of a customer code: the first eight upper-case
297	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
298	     * treated as empty when {@code null}), already in their normalized forms.
299	     */
300	    private String customerCodeHash(String telephone, String lastName) {
301	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
302	        try {
303	            byte[] digest = MessageDigest.getInstance("SHA-256")
304	                .digest(key.getBytes(StandardCharsets.UTF_8));
305	            StringBuilder sb = new StringBuilder();
306	            for (int i = 0; i < 4; i++) {
307	                sb.append(String.format("%02X", digest[i]));
308	            }
309	            return sb.toString();
310	        }
311	        catch (NoSuchAlgorithmException e) {
312	            throw new IllegalStateException(e);
313	        }
314	    }
315	
316	    /**
317	     * Count the existing owners whose city matches the given one, compared after
318	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
319	     * cap: a city that already holds this many owners is at capacity.
320	     */
321	    private long countOwnersInCity(String city) {
322	        String normalizedCity = normalizeForHousehold(city);
323	        return this.clinicService.findAllOwners().stream()
324	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
325	            .count();
326	    }
327	
328	    /**
329	     * Count the existing owners whose registration date falls on the given day. Used to
330	     * enforce the per-day create limit: once this many owners have been registered today,
331	     * the day is at capacity and further creates are rejected.
332	     */
333	    private long countOwnersRegisteredOn(LocalDate day) {
334	        return this.clinicService.findAllOwners().stream()
335	            .filter(existing -> day.equals(existing.getRegistrationDate()))
336	            .count();
337	    }
338	
339	    /**
340	     * Roll a registration date forward to the next business day: a date falling on a
341	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
342	     * returned unchanged.
343	     */
344	    private LocalDate toBusinessDay(LocalDate date) {
345	        DayOfWeek dayOfWeek = date.getDayOfWeek();
346	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
347	            return date.plusDays(8 - dayOfWeek.getValue());
348	        }
349	        return date;
350	    }
351	
352	    /**
353	     * Find the existing owners that already belong to the same household as the given
354	     * computed household id. Because the household id is derived deterministically from
355	     * the owner's (last name, postcode), this is exactly the set of other owners sharing
356	     * that last name and postcode.
357	     */
358	    private List<Owner> findHouseholdMembers(String householdId) {
359	        if (householdId == null) {
360	            return List.of();
361	        }
362	        return this.clinicService.findAllOwners().stream()
363	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
364	            .toList();
365	    }
366	
367	    /**
368	     * Find an existing owner that this new owner softly duplicates: one sharing the same
369	     * last name (compared case-insensitively after whitespace normalization) and the same
370	     * postcode, but with a different telephone. Returns the lowest-id such owner, or
371	     * {@code null} when the new owner has no postcode or no soft match exists. Owners
372	     * whose telephone equals the new owner's are excluded, as those are governed by the
373	     * hard-duplicate (identityKey) check rather than this soft match.
374	     */
375	    private Owner findPossibleDuplicate(Owner owner) {
376	        String postcode = owner.getPostcode();
377	        if (postcode == null) {
378	            return null;
379	        }
380	        String normalizedLastName = normalizeForHousehold(owner.getLastName());
381	        String telephone = owner.getTelephone();
382	        return this.clinicService.findAllOwners().stream()
383	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
384	                && postcode.equals(existing.getPostcode())
385	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
386	            .min(java.util.Comparator.comparing(Owner::getId))
387	            .orElse(null);
388	    }
389	
390	    /**
391	     * Count the existing owners that already share both the given first and last
392	     * name, compared case-insensitively. Used to populate an owner's namesake count
393	     * at creation time, reflecting how many owners with the same name existed before
394	     * this one was created.
395	     */
396	    private int countNamesakes(String firstName, String lastName) {
397	        String normalizedFirstName = normalizeName(firstName);
398	        String normalizedLastName = normalizeName(lastName);
399	        return (int) this.clinicService.findAllOwners().stream()
400	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
401	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
402	            .count();
403	    }
404	
405	    private String normalizeName(String value) {
406	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
407	    }
408	
409	    /**
410	     * Build the deterministic identifier shared by all owners of one household: the first
411	     * 12 hex characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}.
412	     * Because it depends only on the (last name, postcode) pair, every owner at the same last
413	     * name and postcode resolves to the same value regardless of creation order.
414	     */
415	    private String householdId(String lastName, String postcode) {
416	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
417	        try {
418	            byte[] digest = MessageDigest.getInstance("SHA-256")
419	                .digest(key.getBytes(StandardCharsets.UTF_8));
420	            StringBuilder sb = new StringBuilder();
421	            for (int i = 0; i < 6; i++) {
422	                sb.append(String.format("%02x", digest[i]));
423	            }
424	            return sb.toString();
425	        }
426	        catch (NoSuchAlgorithmException e) {
427	            throw new IllegalStateException(e);
428	        }
429	    }
430	
431	    private String normalizeForHousehold(String value) {
432	        if (value == null) {
433	            return "";
434	        }
435	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
436	    }
437	
438	    private String normalizeTelephone(String telephone) {
439	        if (telephone == null) {
440	            return null;
441	        }
442	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
443	        String digits;
444	        if (cleaned.startsWith("+")) {
445	            digits = cleaned.substring(1);
446	        } else {
447	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
448	            digits = "61" + national;
449	        }
450	        if (!digits.matches("[0-9]{8,15}")) {
451	            return null;
452	        }
453	        if (!hasValidNationalLength(digits)) {
454	            return null;
455	        }
456	        return "+" + digits;
457	    }
458	
459	    /**
460	     * Validate the national-number length of an E.164 number (the digits, without the
461	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
462	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
463	     * codes without a known rule are accepted as-is.
464	     */
465	    private boolean hasValidNationalLength(String digits) {
466	        if (digits.startsWith("61")) {
467	            return digits.length() - 2 == 9;
468	        }
469	        if (digits.startsWith("1")) {
470	            return digits.length() - 1 == 10;
471	        }
472	        return true;
473	    }
